def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for _, b in history:
        if b == 'D':
            opp_def += 1

    if history[0][1] == 'D':
        return 'D'

    if opp_def > 0:
        if opp_def > n * 0.7:
            return 'D'
        if n >= 3:
            last3_def = True
            for i in range(n - 3, n):
                if history[i][1] != 'D':
                    last3_def = False
                    break
            if last3_def:
                return 'D'
        last_my, last_opp = history[-1]
        if last_my == 'D' and last_opp == 'D':
            return 'C'
        if last_my == 'D':
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n == 5:
        return 'D'
    if n == 6:
        return 'C'
    if n == 7:
        if history[6][1] == 'D':
            return 'C'
        else:
            return 'D'

    if n >= 8:
        if history[7][0] == 'D':
            recent_def = 0
            start = max(0, n - 5)
            for i in range(start, n):
                if history[i][1] == 'D':
                    recent_def += 1
            if recent_def >= 2:
                return 'C'
            return 'D'
        else:
            if n >= 3:
                last3_def = True
                for i in range(n - 3, n):
                    if history[i][1] != 'D':
                        last3_def = False
                        break
                if last3_def:
                    return 'D'
            last_my, last_opp = history[-1]
            if last_my == 'D' and last_opp == 'D':
                return 'C'
            if last_my == 'D':
                return 'C'
            if last_opp == 'D':
                return 'D'
            return 'C'

    return 'C'
